def count_older_than_60(details):
    count = 0
    for detail in details:
        if detail[10] == 'M':
            age = int(detail[11:13])
            if age > 60:
                count += 1
    return count

class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        def get_or(nums):
            return sum(nums)

        def get_or_after_k_operations(nums, k):
            nums.sort(reverse=True)
            for i in range(k):
                nums[i] *= 2
            return get_or(nums)

        return max(get_or_after_k_operations(nums, k), get_or(nums))
