class Solution:
    def sumOfPower(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        dp = [0] * (n + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            dp[i] = dp[i - 1] * nums[i - 1] % MOD
            dp[i] = (dp[i] + dp[i - 1]) % MOD
        return (dp[n] - 1) % MOD

def longest_semi_repetitive_substring(s):
    n = len(s)
    max_len = 0
    for i in range(n):
        count = 1
        for j in range(i + 1, n):
            if s[j] == s[j - 1]:
                count += 1
                if count > 1:
                    break
            else:
                count = 1
            max_len = max(max_len, j - i + 1)
    return max_len

def findLosers(n, k):
    received = set()
    current = 0
    received.add(current)
    while True:
        next_pos = (current + k) % n
        received.add(next_pos)
        current = next_pos
        if current in received:
            break
    return sorted(list(received))

