class Solution:
    def minCost(self, cost: List[int], time: List[int]) -> int:
        n = len(cost)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        for i in range(n):
            for j in range(i, n):
                dp[j + 1] = min(dp[j + 1], dp[j] + cost[i])
