class Solution:
    def minCost(self, nums, x):
        n = len(nums)
        dp = [float('inf')] * n
        dp[0] = nums[0]
        for i in range(1, n):
            dp[i] = min(dp[i-1] + nums[i], dp[i-1] + x + nums[i])
        return min(dp)

def minimizedStringLength(s: str) -> int:
    stack = []
    for c in s:
        if c == 'a':
            stack.append(c)
        else:
            if stack:
                stack.pop()
    return len(stack)

