class Solution:
    def maxNonDecreasingLength(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        dp = [[0] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
        for i in range(n - 1):
            if nums1[i] <= nums2[i]:
                dp[i][i + 1] = max(dp[i][i + 1], dp[i][i] + 1)
            if nums2[i] <= nums1[i]:
                dp[i][i + 1] = max(dp[i][i + 1], dp[i][i] + 1)
        return max(max(row) for row in dp)

