def count_employees_meeting_target(hours, target):
    count = 0
    for hour in hours:
        if hour >= target:
            count += 1
    return count

def find_min_length_string(a, b, c):
    def lcp(x, y, z):
        min_len = min(len(x), len(y), len(z))
        lcp_str = []
        for i in range(min_len):
            if x[i] == y[i] == z[i]:
                lcp_str.append(x[i])
            else:
                break
        return ''.join(lcp_str)

    lcp_str = lcp(a, b, c)
    a_part = a[len(lcp_str):]
    b_part = b[len(lcp_str):]
    c_part = c[len(lcp_str):]
    return a_part + b_part + c_part

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        forbidden_set = set(forbidden)
        n = len(word)
        dp = [0] * n
        dp[0] = 1
        for i in range(1, n):
            if word[i] not in forbidden_set:
                dp[i] = dp[i-1] + 1
            else:
                dp[i] = 0
        return max(dp)

def permute(s):
    vowels = 'aeiouAEIOU'
    vowels_sorted = sorted(vowels)
    vowels_sorted_index = {v: i for i, v in enumerate(vowels_sorted)}

    result = list(s)
    vowel_index = 0

    for char in result:
        if char in vowels_sorted:
            result[result.index(char)] = vowels_sorted_index[char]
            vowel_index += 1

    return ''.join(result)
def sort_descending(arr):
    # Implementing a simple bubble sort algorithm to sort the list in descending order
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] < arr[j+1]:
                # Swap if the element found is less than the next element
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

