def is_good(nums):
    n = max(nums)
    if len(nums) != n + 1:
        return False
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1
    # Check for each number from 1 to n-1 exactly once
    for i in range(1, n):
        if counts.get(i, 0) != 1:
            return False
    # Check for n exactly twice
    if counts.get(n, 0) != 2:
        return False
    return True

def max_pair_sum(nums):
    def max_digit(n):
        return max(int(d) for d in str(n))

    max_sum = -1
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if max_digit(nums[i]) == max_digit(nums[j]):
                max_sum = max(max_sum, nums[i] + nums[j])
    return max_sum

