def countBeautifulNumbers(low, high, k):
    def is_beautiful(n):
        even_count = 0
        odd_count = 0
        for digit in str(n):
            if int(digit) % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
        return even_count == odd_count and n % k == 0

    return sum(1 for n in range(low, high + 1) if is_beautiful(n))
