    n = len(s1)
    dp = [[float('inf')] * n for _ in range(n)]
    dp[0][0] = 0
    for i in range(n):
        for j in range(i + 1):
            if s1[i] == s2[j]:
                dp[i + 1][j + 1] = min(dp[i + 1][j + 1], dp[i][j] + x)
