class Solution:
    def countPoints(self, nums: List[List[int]]) -> int:
        res = 0
        for start, end in nums:
            res += end - start + 1
        return res

import math

def is_square(x):
    return int(math.sqrt(x))**2 == x

def max_element_sum(nums):
    n = len(nums)
    ans = 0
    for i in range(1, n+1):
        if is_square(nums[i-1]):
            ans = max(ans, nums[i-1])
    return ans
class Solution:
    def addTwoNumbers(self, l1: ListNode, l2: ListNode) -> ListNode:
        """
        :type l1: ListNode
        :type l2: ListNode
        :rtype: ListNode
        """
        if l1 is None or l2 is None:
            return None

        carry = 0
        result = ListNode(0)

        while l1 or l2 or carry:
            x = l1.val if l1 else 0
            y = l2.val if l2 else 0
            z = carry
            carry = x + y + z
            result.next = ListNode(z)
            result = result.next

            if x != 0:
                l1 = l1.next
            if y != 0:
                l2 = l2.next

        return result.next

