def maxSubarrays(nums):
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        dp[i] = dp[i - 1]
        for j in range(i - 1, -1, -1):
            dp[i] = min(dp[i], dp[j] & nums[i - 1])
    return dp[n]
