class Solution:
    def minLength(self, nums: List[int]) -> int:
        if not nums:
            return 0

        i = 0
        while i < len(nums) - 1:
            if nums[i] < nums[i + 1]:
                nums.pop(i)
                i -= 1
            else:
                i += 1

        return len(nums)

def sum_of_elements_with_k_set_bits(nums, k):
    def count_set_bits(n):
        return bin(n).count('1')

    return sum(nums[i] for i in range(len(nums)) if count_set_bits(i) == k)
class Solution:
    def addTwoNumbers(self, l1: ListNode, l2: ListNode) -> ListNode:
        """
        :type l1: ListNode
        :type l2: ListNode
        :rtype: ListNode
        """
        if not l1 or not l2:
            return l1 or l2

        carry = 0
        result = ListNode(0)

        while l1 or l2 or carry:
            x = l1.val if l1 else 0
            y = l2.val if l2 else 0
            z = carry
            carry = x + y + z
            result.next = ListNode(carry % 10)
            result = result.next
            l1 = l1.next if l1 else None
            l2 = l2.next if l2 else None

        return result

from collections import Counter

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        count = Counter(nums)
        if len(count) < 2:
            return -1

        operations = 0
        while len(count) > 1:
            for key in count:
                if count[key] == 1:
                    continue

                if count[key] == 3:
                    operations += 1
                    count[key] -= 3
                    count[key] -= 1
                    count[key] -= 1
                elif count[key] == 2:
                    operations += 1
                    count[key] -= 2
                    count[key] -= 1
                else:
                    return -1

        return operations

class Solution:
    def countHappyStudents(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            ans += (n - i - 1) * (n - i - 2) // 2
        return ans
