def longest_subsequence(nums, target):
    dp = [0] * (target + 1)
    dp[0] = 1
    for num in nums:
        for i in range(target, num - 1, -1):
            dp[i] = max(dp[i], dp[i - num] + 1)
    return dp[target] if dp[target] > 0 else -1

class Solution:
    def maximumSumOfHeights(self, maxHeights: List[int]) -> int:
        n = len(maxHeights)
        dp = [0] * n
        dp[0] = maxHeights[0]
        for i in range(1, n):
            dp[i] = maxHeights[i]
            for j in range(i):
                if maxHeights[j] >= maxHeights[i]:
                    dp[i] = max(dp[i], dp[j] + maxHeights[i])
        return max(dp)

