def min_changes_to_beautiful(s):
    count = 0
    for i in range(0, len(s), 2):
        if s[i] != s[i+1]:
            count += 1
    return count

def findChampion(grid):
    n = len(grid)
    champion = 0
    for i in range(n):
        for j in range(n):
            if i != j and grid[i][j] == 1:
                champion = j
                break
    return champion

def min_operations(nums1, nums2):
    n = len(nums1)
    max1 = max(nums1)
    max2 = max(nums2)

    if max1 == max2:
        return 0

    if max1 > max2:
        max1, max2 = max2, max1

    if max1 == max2:
        return -1

    if max1 == max2 + 1:
        return 1

    if max1 == max2 + 2:
        return 2

    return -1

from collections import Counter

class Solution:
    def maxFrequency(self, nums, k):
        nums.sort()
        left = 0
        right = len(nums) - 1
        ans = 0
        while left < right:
            mid = (left + right) // 2
            if nums[mid] - nums[mid - 1] <= k:
                ans = mid
                left = mid + 1
            else:
                right = mid - 1
        return ans

def canMakePalindromeQueries(s, queries):
    n = len(s)
    ans = []
    for a, b, c, d in queries:
        s1 = s[a:b+1]
        s2 = s[c:d+1]
        s1_sorted = sorted(s1)
        s2_sorted = sorted(s2)
        if s1_sorted == s2_sorted:
            ans.append(True)
        else:
            ans.append(False)
    return ans
