def find_occurrences(nums1, nums2):
    set_nums2 = set(nums2)
    count1 = 0
    for num in nums1:
        if num in set_nums2:
            count1 += 1
    count2 = 0
    for num in nums2:
        if num in set_nums2:
            count2 += 1
    return [count1, count2]

def min_coins(prices):
    n = len(prices)
    dp = [float('inf')] * (n + 1)
    dp[1] = 0
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            dp[i] = min(dp[i], dp[i - j] + prices[j - 1])
    return dp[n]

class Solution:
    def maxNonDecreasingLength(self, nums: List[int]) -> int:
        if not nums:
            return 0

        n = len(nums)
        dp = [1] * n

        for i in range(1, n):
            for j in range(i):
                if nums[i] >= nums[j]:
                    dp[i] = max(dp[i], dp[j] + 1)

        return max(dp)

class Solution:
    def lexicographicallySmallestArray(self, nums, limit):
        nums.sort()
        for i in range(len(nums)):
            if nums[i] != i + 1:
                nums[i], nums[i + 1] = nums[i + 1], nums[i]
        return nums
