class Solution:
    def findErrorNums(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        nums = set()
        for i in range(n):
            for j in range(n):
                nums.add(grid[i][j])
        nums = list(nums)
        nums.sort()
        for i in range(n):
            if nums[i] == i + 1:
                return [i + 1, nums[i] + 1]
        return [nums[n - 1], nums[0]]

def minCostToEqualindromic(nums):
    def is_palindrome(x):
        return str(x) == str(x)[::-1]

    def cost(x):
        return sum(abs(num - x) for num in nums)

    def find_min_cost(nums):
        min_cost = float('inf')
        for y in range(1, 10**9):
            if is_palindrome(y):
                min_cost = min(min_cost, cost(y))
        return min_cost

    return find_min_cost(nums)
class Solution:
    def addTwoNumbers(self, l1: ListNode, l2: ListNode) -> ListNode:
        """
        :type l1: ListNode
        :type l2: ListNode
        :rtype: ListNode
        """
        if l1 is None:
            return l2
        if l2 is None:
            return l1

        carry = 0
        result = ListNode(0)

        while l1 or l2 or carry:
            x = l1.val if l1 else 0
            y = l2.val if l2 else 0
            total = x + y + carry
            carry = total // 10
            result.next = ListNode(total % 10)
            result = result.next

            if l1:
                l1 = l1.next
            if l2:
                l2 = l2.next

        return result

def remove_adjacent_almost_equal(word):
    i = 0
    while i < len(word) - 1:
        if abs(ord(word[i]) - ord(word[i + 1])) == 1:
            i += 1
        else:
            i += 1
    return i
class Solution:
    def isPalindrome(self, s: str) -> bool:
        if len(s) <= 1:
            return True
        for i in range(len(s) // 2):
            if s[i] != s[len(s) - 1 - i]:
                return False
        return True

def minCost(source, target, original, changed, cost):
    n = len(source)
    dp = [[float('inf')] * 26 for _ in range(n)]
    dp[0][ord(source[0]) - ord('a')] = 0
    for i in range(1, n):
        for j in range(26):
            if dp[i - 1][j] == float('inf'):
                continue
            for k in range(26):
                if k != j:
                    dp[i][k] = min(dp[i][k], dp[i - 1][j] + cost[k])
    return dp[n - 1][ord(target[0]) - ord('a')] if dp[n - 1][ord(target[0]) - ord('a')] != float('inf') else -1

from collections import defaultdict

def total_frequencies(nums):
    freq = defaultdict(int)
    for num in nums:
        freq[num] += 1
    max_freq = max(freq.values())
    return sum(1 for num, count in freq.items() if count == max_freq)

