def has_trailing_zero(nums):
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if (nums[i] | nums[j]) & (nums[i] | nums[j]) == 0:
                return True
    return False

def min_operations(nums, k):
    n = len(nums)
    ans = 0
    for i in range(n):
        if nums[i] ^ k == 0:
            ans += 1
        else:
            ans += 1
            nums[i] ^= k
    return ans
