class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            ans += self.count(nums, i, n)
        return ans

    def count(self, nums, i, n):
        ans = 0
        for j in range(i, n):
            if nums[j] > nums[j - 1]:
                ans += 1
        return ans

class Solution:
    def maxSubArray(self, nums: List[int], k: int) -> int:
        if len(nums) < 2:
            return 0

        max_sum = float('-inf')
        for i in range(len(nums)):
            for j in range(i+1, len(nums)):
                if abs(nums[i] - nums[j]) == k:
                    max_sum = max(max_sum, nums[i] + nums[j])
        return max_sum

def max_subset(nums):
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        dp[i] = dp[i - 1]
        for j in range(1, i + 1):
            if (i % 2 == 0 and j % 2 == 0) or (i % 2 == 1 and j % 2 == 1):
                dp[i] = max(dp[i], dp[i - j] + 1)
    return dp[n]

def countPrefixAndSuffixPairs(words):
    count = 0
    n = len(words)
    for i in range(n):
        for j in range(i + 1, n):
            if isPrefixAndSuffix(words[i], words[j]):
                count += 1
    return count

def isPrefixAndSuffix(s1, s2):
    return s2.startswith(s1) and s2.endswith(s1)

def ant_on_boundary(nums):
    current_position = 0
    count = 0
    for num in nums:
        current_position += abs(num)
        if current_position == 0:
            count += 1
    return count

def maxPalindromes(words):
    def isPalindrome(s):
        return s == s[::-1]

    def swap(i, j, x, y):
        words[i][x], words[j][y] = words[j][y], words[i][x]

    n = len(words)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if isPalindrome(words[i]):
                dp[i][j] = 1
            for k in range(i, j):
                if isPalindrome(words[k]):
                    dp[i][j] = max(dp[i][j], dp[i][k] + dp[k + 1][j])

    return max(dp[0][n - 1])

