import sys

def find_unique_index(s):
    # Create a dictionary to count occurrences of each character
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the character that appears only once
    unique_char = None
    for char, count in char_count.items():
        if count == 1:
            unique_char = char
            break

    # Find the index of the unique character
    for index, char in enumerate(s):
        if char == unique_char:
            return index + 1  # Return 1-based index

