    n = len(apple)
    m = len(capacity)
    dp = [[0 for _ in range(m+1)] for _ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, m+1):
            dp[i][j] = dp[i-1][j]
            if j >= apple[i-1]:
                dp[i][j] = min(dp[i][j], dp[i-1][j-apple[i-1]] + 1)
