def longest_subarray(nums):
    if not nums:
        return 0

    max_len = 1
    current_len = 1

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            current_len += 1
            max_len = max(max_len, current_len)
        elif nums[i] < nums[i - 1]:
            current_len = 1

    return max_len

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def max_prime_distance(nums):
    max_distance = 0
    for i in range(len(nums)):
        if is_prime(nums[i]):
            max_distance = max(max_distance, i - nums.index(nums[i]))
    return max_distance

