def find_x(nums1, nums2):
    n = len(nums1)
    diffs = [nums1[i] - nums2[i] for i in range(n)]
    first = diffs[0]
    for d in diffs[1:]:
        if d != first:
            return 0
    return first

class Solution:
    def findMedianOfUniquenessArray(self, nums: List[int]) -> int:
        n = len(nums)
        count = [0] * (n + 1)
        for i in range(n):
            count[nums[i]] += 1

        distinct = [0] * (n + 1)
        for i in range(n):
            distinct[i + 1] = distinct[i] + count[i + 1]

        ans = 0
        for i in range(n + 1):
            ans += distinct[i]
            if i < n:
                ans -= distinct[i - 1]

        return ans

def is_valid_word(word):
    vowels = set('aeiouAEIOU')
    has_vowel = False
    has_consonant = False

    for char in word:
        if char in vowels:
            has_vowel = True
        elif char.isalpha():
            has_consonant = True

        if has_vowel and has_consonant:
            return True

    return False

