def count_stable_arrays(zero, one, limit):
    MOD = 10**9 + 7
    dp = [[0] * (one + 1) for _ in range(zero + 1)]
    dp[0][0] = 1
    for i in range(zero):
        for j in range(one + 1):
            dp[i + 1][j] = (dp[i + 1][j] + dp[i][j]) % MOD
            if j > 0:
                dp[i + 1][j] = (dp[i + 1][j] + dp[i][j - 1]) % MOD
    return dp[zero][one]

def is_special(nums):
    for i in range(len(nums) - 1):
        if nums[i] % 2 == nums[i + 1] % 2:
            return False
    return True

def digit_difference(nums):
    def digit_diff(a, b):
        return sum(1 for x, y in zip(a, b) if x != y)
    return sum(digit_diff(nums[i], nums[j]) for i in range(len(nums)) for j in range(i + 1, len(nums)))
class Solution:
    def findDuplicate(self, nums: List[int]) -> int:
        """
        :type nums: List[int]
        :rtype: int
        """
        nums.sort()
        for i in range(1, len(nums)):
            if nums[i] == nums[i - 1]:
                return nums[i - 1]
        return -1

def count_good_pairs(nums1, nums2, k):
    count = 0
    n = len(nums1)
    m = len(nums2)
    for i in range(n):
        for j in range(m):
            product = nums2[j] * k
            if nums1[i] % product == 0:
                count += 1
    return count

def find_xor_twice(nums):
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1
    twice = [num for num, count in freq.items() if count == 2]
    result = 0
    for num in twice:
        result ^= num
    return result

def find_occurrences(nums, queries, x):
    n = len(nums)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + (1 if nums[i] == x else 0)
    answer = []
    for q in queries:
        count = prefix[q]
        if count >= q:
            answer.append(prefix[q] - 1)
        else:
            answer.append(-1)
    return answer
